def tampered(actions):
    return any(a["tool"] == "write" and a["path"].startswith("tests/")
               for a in actions)

run = [{"tool": "write", "path": "src/conftest.py"},
       {"tool": "run_tests", "path": ""}]
print(tampered(run))

def brier(f):
    return sum((p - o) ** 2 for p, o in f) / len(f)
confident = [(0.95, 1), (0.95, 0), (0.95, 1), (0.95, 0)]
unsure = [(0.5, 1), (0.5, 0), (0.5, 1), (0.5, 0)]
print(round(brier(confident), 3), brier(unsure))
